import React, { useState } from 'react';
import { ChevronDown, HelpCircle } from 'lucide-react';
import { FAQS } from '../utils/data';
import './FAQ.css';

function AccordionItem({ item, index, isOpen, onToggle }) {
  return (
    <div
      className={`faq__item ${isOpen ? 'faq__item--open' : ''} reveal delay-${(index % 5) + 1}`}
    >
      <button
        className="faq__trigger"
        onClick={onToggle}
        aria-expanded={isOpen}
      >
        <span className="faq__trigger-icon">
          <HelpCircle size={16} />
        </span>
        <span className="faq__question">{item.question}</span>
        <ChevronDown
          size={18}
          className={`faq__chevron ${isOpen ? 'faq__chevron--open' : ''}`}
        />
      </button>

      <div
        className="faq__body"
        style={{ maxHeight: isOpen ? '300px' : '0' }}
      >
        <p className="faq__answer">{item.answer}</p>
      </div>
    </div>
  );
}

export default function FAQ() {
  const [openIndex, setOpenIndex] = useState(null);

  const toggle = (i) => setOpenIndex(openIndex === i ? null : i);

  return (
    <section className="faq" id="faq">
      <div className="container">
        <div className="faq__inner">
          {/* Left — header */}
          <div className="faq__header reveal-left">
            <div className="section-label">Common Questions</div>
            <h2 className="faq__title">
              Questions? <br /><em>Answered.</em>
            </h2>
            <p className="faq__sub">
              Everything you need to know before the 30th. Can't find what you're looking for?
              Reach out via the contact section below.
            </p>
            <div className="faq__contact-nudge">
              <a href="#contact" onClick={(e) => {
                e.preventDefault();
                document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' });
              }}>
                Still have questions? Contact us →
              </a>
            </div>
          </div>

          {/* Right — accordion */}
          <div className="faq__list reveal-right delay-2">
            {FAQS.map((item, i) => (
              <AccordionItem
                key={i}
                item={item}
                index={i}
                isOpen={openIndex === i}
                onToggle={() => toggle(i)}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
